function validate([stoneValue]) {
  if (!Array.isArray(stoneValue) || stoneValue.length < 1 || stoneValue.length > 500) return 'stoneValue needs 1 to 500 values.';
  if (stoneValue.some(v => !Number.isInteger(v) || v < 1 || v > 1000000)) return 'Each stone value is an integer from 1 to 10^6.';
  return null;
}

