function stoneGameV(stoneValue) {
  const n = stoneValue.length;
  const prefix = new Array(n + 1).fill(0);
  for (let i = 0; i < n; i++) {
    prefix[i + 1] = prefix[i] + stoneValue[i];
  }
  const dp = Array.from({ length: n }, () => new Array(n).fill(0));

  for (let length = 2; length <= n; length++) {
    for (let left = 0; left + length - 1 < n; left++) {
      const right = left + length - 1;
      let best = 0;
      for (let mid = left; mid < right; mid++) {
        const leftSum = prefix[mid + 1] - prefix[left];
        const rightSum = prefix[right + 1] - prefix[mid + 1];
        if (leftSum < rightSum) {
          best = Math.max(best, leftSum + dp[left][mid]);
        } else if (leftSum > rightSum) {
          best = Math.max(best, rightSum + dp[mid + 1][right]);
        } else {
          best = Math.max(best, leftSum + Math.max(dp[left][mid], dp[mid + 1][right]));
        }
      }
      dp[left][right] = best;
    }
  }
  return dp[0][n - 1];
}

