function stoneGameV(stoneValue) {
  const total = (row) => row.reduce((a, b) => a + b, 0);
  const play = (row) => {
    if (row.length === 1) return 0;
    let most = 0;
    for (let cut = 1; cut < row.length; cut++) {
      const first = row.slice(0, cut), second = row.slice(cut);
      const a = total(first), b = total(second);
      if (a <= b) most = Math.max(most, a + play(first));
      if (b <= a) most = Math.max(most, b + play(second));
    }
    return most;
  };
  return play(stoneValue);
}

