function generate(rand, size) {
  // Large rows stop near 220 stones so the O(n^3) DP stays well inside the app's 2-second limit.
  const n = size === 'large' ? 150 + Math.floor(rand() * 71) : 1 + Math.floor(rand() * 9);
  const top = size === 'large' ? (rand() < 0.5 ? 1000000 : 1 + Math.floor(rand() * 4)) : (rand() < 0.5 ? 3 : 20);
  return [Array.from({ length: n }, () => 1 + Math.floor(rand() * top))];
}
